internal final class NDXInventTableTransferProcess extends NDXTransferToD365 implements NDXTransferToD365Interface
{
}

Method.Source:
private void writeInventTable(Niedax.AX.TableRecordModels.TableRecord _record)
{
    System.Exception ex;

    Niedax.AX.TableRecordModels.InventTable inventTable = _record;
    InventTable lInventTable;
    ItemIdBase itemId;
    DataAreaId dataAreaId;

    str message = strFmt("InventTable %1 writeInventTable on %2", inventTable.ToString(), this.environment);

    try
    {
        itemId = inventTable.ItemId;
        dataAreaId = inventTable.DataAreaId;
        changecompany(dataAreaId)
        {
            lInventTable = InventTable::find(itemId);
        }


        if(!lInventTable)
        {
            message = strFmt("Record %1 does not exist on %2",  inventTable.ToString(), this.environment);
            throw Error(message);
        }
        else
        {
            //Make only updates on an existing record, since the records are created by determination process in d365
            //Right now we do nothing
            message = strFmt("InventTable %1 inserted or found on %2", inventTable.ToString(), this.environment);
            response.RecId = lInventTable.RecId;
            response.Success = true;
        }

    }
    catch(ex)
    {
        message = message + "-" + ex.Message;
        response.RecId = 0;
    }

    response.Message = message;


}

/// <summary>
/// Updates or creates corresponding record
/// </summary>
/// <param name = "_record">record instance</param>
/// <returns>Response</returns>
public Niedax.D365.API.Models.D365_APIResponse writeRecord(Niedax.AX.TableRecordModels.TableRecord _record)
{
    this.writeInventTable(_record);
    return response;
}
